CAUSE_BY_CLASS: dict[str, list[str]] = {}
for _cid, _c in CAUSES.items():
    CAUSE_BY_CLASS.setdefault(_c["cls"], []).append(_cid)

assert set(CAUSE_BY_CLASS) == set(CLASSES), "every class needs causes"

# Components used for the "which component failed?" question
COMPONENTS = sorted({c["comp"] for c in CAUSES.values()} | {c["comp"] for c in CLASSES.values()})

SERVICES = ["checkout", "billing", "inventory", "search-api", "notifications", "auth-gateway", "reports", "ingest", "orders", "profiles"]
